import type { ChangelogConfig } from "../types";
import type { Release } from "./parse-changelog";

export const generatedMarker =
  "{/* generated by scripts/sync-changelog.ts, edit the changelog file instead */}";

function releaseId(version: string) {
  if (version === "Unreleased") return "unreleased";
  return `v${version
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-|-$/g, "")}`;
}

function renderRelease({ version, date, body }: Release) {
  const label = version.replace(/[\\`*_{}<>[\]]/g, "\\$&");
  const attributes = date ? ` date="${date}"` : "";
  return `<Release${attributes}>\n\n## ${label} [#${releaseId(version)}]\n\n${body}\n\n</Release>`;
}

/**
 * @name renderChangelogPage
 * @description Builds the MDX source of the generated changelog page: the
 * frontmatter, a marker that identifies the file as generated and one
 * `Release` block per release. The sidebar badge shows the latest version.
 *
 * @example
 * await Bun.write("content/docs/changelog.mdx", renderChangelogPage(releases, config, false))
 */
export function renderChangelogPage(
  releases: Release[],
  config: ChangelogConfig,
  editUrl: string | false,
) {
  const latest = releases.find((release) => release.version !== "Unreleased");
  const frontmatter = [
    `title: ${JSON.stringify(config.title)}`,
    `description: ${JSON.stringify(config.description)}`,
    ...(latest ? [`sidebarBadge: ${JSON.stringify(latest.version)}`] : []),
    `tocDepth: 2`,
    `editUrl: ${JSON.stringify(editUrl)}`,
  ];
  return `---\n${frontmatter.join("\n")}\n---\n\n${generatedMarker}\n\n${releases.map(renderRelease).join("\n\n")}\n`;
}
